
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_optb86b_vdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_optb86b_vdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.244174487776218e+00, -4.161542716982770e+00, -4.045825569858398e+00, -3.885677373738937e+00, -3.667775472944234e+00, -3.378464935602000e+00, -3.007653186546797e+00, -2.555940882873836e+00, -2.044603961628089e+00, -1.521135923995218e+00, -1.032068370911106e+00, -6.950893658585664e-01, -5.966648096051526e-01, -4.894187429838936e-01, -3.540531478036098e-01, -2.305193322998383e-01, -1.405960565644152e-01, -7.026883107782242e-02, -2.376631098761038e-02, -5.442054093406899e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


